  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Compute the final booking price after applying membership discount rules.
   * Algorithm:
   * 1. If customer is null or bookingTime is null, return price.
   * 2. If customer.membershipPackage is null, return price.
   * 3. If membershipPackage does not contain Award.DISCOUNTS, return price.
   * 4. Check whether bookingTime is at least 24 hours before this trip’s departureTime.
   * 5. If not at least 24 hours early, return price.
   * 6. Otherwise compute discountedPrice = price * 0.8.
   * 7. Round the result to one decimal place and return it.
   * Related Features:
   * - price
   * - departureTime
   * - calculateDiscountedPrice(customer, bookingTime)
   * - MembershipPackage.hasAward(award)
   * - Customer.membershipPackage
   * Related Classes: Customer, MembershipPackage, Award
   * Input:
   * - customer: booking customer; may be null.
   * - bookingTime: booking timestamp as String; may be null.
   * Output:
   * - double:
   *   - original price if discount conditions are not met.
   *   - discounted price rounded to one decimal place if eligible.
   * Pre-condition:
   * - Trip has a valid price and departureTime.
   * - customer and bookingTime, if provided, are parsable.
   * Post-condition:
   * - No state is modified.
   * - The returned amount respects the 20% discount rule and one-decimal rounding.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null)
    {
      return price;
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null)
    {
      return price;
    }
    if (!membershipPackage.hasAward(Award.DISCOUNTS))
    {
      return price;
    }
    if (departureTime == null)
    {
      return price;
    }
    try
    {
      java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
      java.time.LocalDateTime bookingDateTime = java.time.LocalDateTime.parse(bookingTime, formatter);
      java.time.LocalDateTime departureDateTime = java.time.LocalDateTime.parse(departureTime, formatter);
      java.time.Duration duration = java.time.Duration.between(bookingDateTime, departureDateTime);
      if (duration.toHours() < 24)
      {
        return price;
      }
    }
    catch (Exception e)
    {
      return price;
    }
    double discountedPrice = price * 0.8;
    return Math.round(discountedPrice * 10.0) / 10.0;
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Compute reward points earned from bookings on this trip for a specific customer and month.
   * Algorithm:
   * 1. If customer is null or currentMonth is null, return 0.
   * 2. For each booking in this trip’s bookings:
   *    - If booking.customer equals the given customer and booking.isInMonth(currentMonth) is true,
   *      add booking.numberOfSeats * 5 to total.
   * 3. Return total.
   * Related Features:
   * - bookings
   * - calculateMonthlyPoints(customer, currentMonth)
   * - Booking.isInMonth(month)
   * - Booking.numberOfSeats
   * - Booking.customer
   * Related Classes: Booking, Customer
   * Input:
   * - customer: customer whose points are being computed; may be null.
   * - currentMonth: month identifier; may be null.
   * Output:
   * - int:
   *   - total points earned for bookings on this trip in the requested month.
   *   - 0 if invalid inputs.
   * Pre-condition:
   * - Trip exists.
   * - Bookings list is initialized.
   * - currentMonth is a supported month format.
   * Post-condition:
   * - No state is modified.
   * - The returned value equals 5 times the total booked seats for matching bookings.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || currentMonth == null)
    {
      return 0;
    }
    int total = 0;
    if (bookings != null)
    {
      for (Booking booking : bookings)
      {
        if (booking != null && customer.equals(booking.getCustomer()) && booking.isInMonth(currentMonth))
        {
          total += booking.getNumberOfSeats() * 5;
        }
      }
    }
    return total;
  }

